import pytest
from pricing.quote import quote
from pricing.tiers import tier_for
from pricing.discounts import discount_rate


def test_quote_keys():
    q = quote(10.0, 2)
    assert set(q.keys()) == {"tier", "rate", "subtotal", "total"}


def test_negative_amount_raises():
    with pytest.raises(ValueError):
        quote(-1.0, 5)


def test_negative_units_raises():
    with pytest.raises(ValueError):
        quote(10.0, -1)


def test_zero_units_subtotal():
    q = quote(25.0, 0)
    assert q["subtotal"] == 0.0


def test_zero_units_total():
    q = quote(25.0, 0)
    assert q["total"] == 0.0


def test_subtotal_is_float():
    q = quote(10.0, 1)
    assert isinstance(q["subtotal"], float)


def test_total_is_float():
    q = quote(10.0, 1)
    assert isinstance(q["total"], float)


def test_zero_units_types_are_float():
    q = quote(0.0, 0)
    assert type(q["subtotal"]) is float and type(q["total"]) is float


def test_tier_matches_tier_for():
    q = quote(15.5, 3)
    assert q["tier"] == tier_for(15.5)


def test_rate_matches_discount_rate():
    tier = tier_for(15.5)
    q = quote(15.5, 3)
    assert q["rate"] == discount_rate(tier, 3)


def test_subtotal_formula():
    q = quote(12.34, 3)
    assert q["subtotal"] == round(12.34 * 3, 2)


def test_total_formula():
    q = quote(12.34, 3)
    assert q["total"] == round((12.34 * 3) * (1 - q["rate"]), 2)


def test_total_lte_subtotal():
    q = quote(50.0, 4)
    assert q["total"] <= q["subtotal"]


def test_subtotal_round_half_to_even_down():
    q = quote(0.125, 1)
    assert q["subtotal"] == 0.12


def test_subtotal_round_half_to_even_up():
    q = quote(0.375, 1)
    assert q["subtotal"] == 0.38


def test_subtotal_float_tie_below():
    q = quote(2.675, 1)
    assert q["subtotal"] == 2.67
